<script setup lang="ts">
import { feedbackRef, toast } from '../feedback'
import AppModal from './AppModal.vue'
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { t } from '../i18n'
const props=defineProps<{csrfToken:string}>(),emit=defineEmits<{expired:[]}>()
const items=ref<{id:string;name:string;enabled:boolean;linked:boolean;username:string}[]>([]),selected=ref(''),localPassword=ref(''),username=ref(''),password=ref(''),error = feedbackRef('error'),busy=ref(false)
async function load(){try{const r=await fetch('/api/account/connectors');if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);items.value=d.connectors}catch(e){error.value=(e as Error).message}}
async function submit(id:string,unlink:boolean){if(busy.value)return;busy.value=true;error.value='';try{const r=await fetch('/api/account/connectors/'+id,{method:unlink?'DELETE':'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({currentPassword:localPassword.value,username:username.value,password:password.value})});if(r.status===401){emit('expired');return};if(!r.ok){const d=await r.json();throw new Error(d.error)};toast(unlink?'账号绑定已解除。':'账号已绑定。');selected.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false;localPassword.value='';password.value=''}}
onMounted(load);onBeforeUnmount(()=>{localPassword.value='';password.value=''})
</script>
<template><section v-if="items.length" class="account-password"><h3>{{ t('外部账号') }}</h3><article v-for="v in items" :key="v.id"><div class="settings-actions"><span>{{ v.name }}{{ v.linked?' / '+v.username:'' }}</span><button v-if="v.enabled||v.linked" class="secondary-button" type="button" :disabled="busy" @click="selected=selected===v.id?'':v.id">{{ t(v.linked?'解除绑定':'绑定账号') }}</button></div><AppModal v-if="selected===v.id" :title="t(v.linked?'解除绑定':'绑定账号')" :busy="busy" @close="selected='';localPassword='';password=''"><form class="settings-form" @submit.prevent="submit(v.id,v.linked)"><fieldset :disabled="busy"><label class="binding-field"><span>{{ t('当前本站密码') }}</span><input v-model="localPassword" type="password" autocomplete="current-password" required /></label><template v-if="!v.linked"><label class="binding-field"><span>{{ t('外部用户名') }}</span><input v-model="username" maxlength="255" required /></label><label class="binding-field"><span>{{ t('外部密码') }}</span><input v-model="password" type="password" autocomplete="off" required /></label></template><button class="primary-button">{{ t('确认') }}</button></fieldset></form></AppModal></article></section></template>
